-- Add skill tree rules and player-owned state without replacing existing saves.
CREATE TABLE public.skill_tree_definitions (name TEXT PRIMARY KEY, data JSONB NOT NULL);
CREATE TABLE public.player_skill_trees (
    player_id TEXT PRIMARY KEY REFERENCES public.players(player_id) ON DELETE CASCADE,
    node_infos JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(node_infos) = 'array'),
    floor_complete_infos JSONB NOT NULL DEFAULT '[]'::jsonb
        CHECK (jsonb_typeof(floor_complete_infos) = 'array')
);
